let html = $json.data || '';
const pageUrl = $json.url || $('URL List').item.json.url || 'unknown';

// Remove non-content blocks at the tag level, before any text extraction.
html = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<nav[\s\S]*?<\/nav>/gi, ' ')
  .replace(/<header[\s\S]*?<\/header>/gi, ' ')
  .replace(/<footer[\s\S]*?<\/footer>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ');

function decodeEntities(str) {
  return str
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const rawTitle = titleMatch ? titleMatch[1].trim() : pageUrl;
const title = decodeEntities(rawTitle).replace(/\s+/g, ' ').trim();

let text = html.replace(/<[^>]+>/g, ' ');
text = decodeEntities(text).replace(/\s+/g, ' ').trim();

if (text.length < 100) {
  // Log the skip instead of silently dropping it, so nightly runs are auditable.
  return [{
    json: {
      url: pageUrl,
      title,
      cleanedText: '',
      skipped: true,
      skipReason: `Only ${text.length} chars extracted (< 100 minimum)`
    }
  }];
}

return [{ json: { url: pageUrl, title, cleanedText: text, skipped: false } }];

function cyrb53(str, seed = 0) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

const hash = cyrb53($json.cleanedText);
return [{ json: { ...$json, contentHash: hash } }];

const original = $('Compute Page Hash1').item.json;
const existingHash = $json.content_hash; // undefined if no prior row (new page)
const changed = !existingHash || existingHash !== original.contentHash;
return [{ json: { ...original, changed } }];

function cyrb53(str, seed = 0) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

const original = $('Compute Page Hash1').item.json;
const text = original.cleanedText;
const title = original.title;
const pageUrl = original.url;

const chunkSize = 800;
const overlap = 150;
const minChunkLength = 40;
const maxChunksPerPage = 200;
const seen = new Set();
const docs = [];
let start = 0;

while (start < text.length && docs.length < maxChunksPerPage) {
  let end = Math.min(start + chunkSize, text.length);
  if (end < text.length) {
    const lastPeriod = text.lastIndexOf('. ', end);
    if (lastPeriod > start + 200) end = lastPeriod + 1;
  }
  const chunk = text.slice(start, end).trim();
  const isBareUrl = /^https?:\/\/\S+$/.test(chunk);

  if (chunk.length > minChunkLength && !isBareUrl && !seen.has(chunk)) {
    seen.add(chunk);
    docs.push({
      json: {
        text: `${title}\n\n${chunk}`,
        source: pageUrl,
        title,
        chunk_index: docs.length,
        content_hash: cyrb53(chunk),
        crawled_at: new Date().toISOString()
      }
    });
  }

  start = end - overlap;
  if (end >= text.length) break;
}

return docs;
